function v3_acceptance(out)
if ~isfile(fullfile(out,'reports/MPC_isolation_regression.json')),v3_regression(out);end
v3_unit(fullfile(out,'config'));v3_verify(out);v3_report(out);v3_source_manifest(out);T=readtable(fullfile(out,'tables','E1_all.csv'));v3_e1_evidence(T,out);T=readtable(fullfile(out,'tables','E2_all.csv'));v3_e2_evidence(T,out);events=dir(fullfile(out,'E2','cases','*','event_metrics.csv'));E=table;for k=1:numel(events),E=[E;readtable(fullfile(events(k).folder,events(k).name))];end;writetable(E,fullfile(out,'tables','E2_event_metrics.csv'));verify=jsondecode(fileread(fullfile(out,'reports','independent_verification.json')));a=jsondecode(fileread(fullfile(out,'reports','acceptance.json')));
old=jsondecode(fileread(fullfile(out,'config','protected_old_raw.json')));oldpass=numel(old)==99;for k=1:numel(old),oldpass=oldpass && strcmp(paper_hash(old(k).path),old(k).sha256);end
pre=jsondecode(fileread(fullfile(out,'config/preflight.json')));assert(~isempty(regexp(pre.git_sha,'^[a-f0-9]{40}$','once')));[code,changed]=system(['git -c core.excludesFile=NUL diff --name-only ' pre.git_sha ' -- simulink/models simulink/data simulink/hpipm simulink/modelgen/build_plant.m simulink/modelgen/build_integrations.m simulink/modelgen/build_actuators_aero.m']);physics_ok=code==0 && isempty(strtrim(changed));paper_json(fullfile(out,'reports/physical_core_git_audit.json'),struct('baseline',pre.git_sha,'passed',physics_ok,'changed_paths',changed,'scope','Tracked formal models, physical data/parameters, existing MPC/allocator source and physical plant generators; build_closedloop has documented output-directory-only changes'));
% Explicit physical unload counterfactual: actual force traces, not zero algebraic command residuals.
F=fullfile(out,'UNLOAD_VALIDATION','cases');d0=load(fullfile(F,'VU_1','sim_output.mat'));d1=load(fullfile(F,'VU_2','sim_output.mat'));t=d0.r.states.Time(:);t=t(t<=d1.r.states.Time(end));ta0=interp1(d0.r.tau_actual.Time,squeeze(d0.r.tau_actual.Data),t);tc0=interp1(d0.r.cmg_torque.Time,squeeze(d0.r.cmg_torque.Data),t);ta1=interp1(d1.r.tau_actual.Time,squeeze(d1.r.tau_actual.Data),t);tc1=interp1(d1.r.cmg_torque.Time,squeeze(d1.r.cmg_torque.Data),t);net=(ta1-ta0)+(tc1-tc0);u=jsondecode(fileread(fullfile(out,'calibration','unload_validation.json')));u.actual_net_difference_rms_Nm=sqrt(mean(sum(net.^2,2)));u.actual_net_difference_peak_Nm=max(vecnorm(net,2,2));u.actual_force_traces_measured=true;u.counterfactual_definition='Closed-loop ON minus OFF, includes feedback response; not an algebraic zero or pure open-loop actuator residual';paper_json(fullfile(out,'reports','E2_unload_physical_evidence.json'),u);writetable(array2table([t,ta1-ta0,tc1-tc0,net],'VariableNames',{'time_s','delta_aero_x','delta_aero_y','delta_aero_z','delta_cmg_x','delta_cmg_y','delta_cmg_z','delta_net_x','delta_net_y','delta_net_z'}),fullfile(out,'tables','E2_unload_actual_net_difference.csv'));
% Required independent E1 evidence and frozen PID audit.
E1=jsondecode(fileread(fullfile(out,'reports','E1_acceptance.json')));E1.protected_inputs_unchanged=a.protected_inputs_unchanged && oldpass && physics_ok;E1.domain_diagnostics_complete=numel(dir(fullfile(out,'E1','cases','*','domain_diagnostics.csv')))==144;E1.analysis_reproducible=verify.reanalysis_pass && verify.cases_checked==249;E1.comparability_pass=verify.E1_pairs_equal;E1.paper_E1_acceptance_complete=E1.matrix_completed && E1.comparability_pass && E1.protected_inputs_unchanged && E1.domain_diagnostics_complete && E1.analysis_reproducible;paper_json(fullfile(out,'reports','E1_acceptance.json'),E1);
regression=jsondecode(fileread(fullfile(out,'reports/MPC_isolation_regression.json')));a.physical_core_unchanged=physics_ok;a.old_raw_unchanged=oldpass;a.independent_verification=verify;a.MPC_isolation_regression=regression.passed;a.E1.paper_acceptance_complete=E1.paper_E1_acceptance_complete;a.E3.paper_acceptance_complete=a.E3.matrix_completed && verify.E3_references_consistent && verify.reanalysis_pass;a.E4.paper_acceptance_complete=a.E4.matrix_completed && verify.E4_conditions_and_PID_frozen && verify.reanalysis_pass;a.E2.paper_acceptance_complete=a.E2.matrix_completed && verify.reanalysis_pass && u.actual_force_traces_measured && u.completed && regression.passed;a.paper_acceptance_complete=a.all_matrices_attempted && a.all_analysis_complete && a.protected_inputs_unchanged && oldpass && physics_ok && E1.paper_E1_acceptance_complete && a.E2.paper_acceptance_complete && a.E3.paper_acceptance_complete && a.E4.paper_acceptance_complete;paper_json(fullfile(out,'reports','acceptance.json'),a);
v3_e3_evidence(out);f=fopen(fullfile(out,'reports','综合报告.md'),'a','n','UTF-8');c=onCleanup(@()fclose(f));fprintf(f,'## 独立验收\n\n独立重算案例 %d，数值重算通过 %d；E1配对一致%d；E3参考一致%d；E4冻结PID和三方法条件一致%d；旧批次99份原始MAT哈希一致%d。\n\n卸载物理验证实际ON−OFF净控制力矩差RMS %.6g Nm、峰值 %.6g Nm。这是不同闭环响应的真实差分，不是指令相消的零，也不能单独证明后续收益。\n\n实验执行验收 complete=%d。任务中的域外、跟踪不佳和控制器回退仍按原状态保留；实验验收通过不代表所有控制任务成功或论文假设全部被支持。E3主迁移阈值受共同启动瞬态污染的限制、E4非固定工况的限制均保留。\n',verify.cases_checked,verify.reanalysis_pass,verify.E1_pairs_equal,verify.E3_references_consistent,verify.E4_conditions_and_PID_frozen,oldpass,u.actual_net_difference_rms_Nm,u.actual_net_difference_peak_Nm,a.paper_acceptance_complete);
% Save per-case provenance without altering immutable original SimulationOutput.
p=jsondecode(fileread(fullfile(out,'config','preflight.json')));cfgs=dir(fullfile(out,'**','case_config.json'));for k=1:numel(cfgs),folder=cfgs(k).folder;s=jsondecode(fileread(fullfile(folder,'case_config.json')));bpath=fullfile(folder,'build_config.json');if ~isfile(bpath),continue;end;b=jsondecode(fileread(bpath));paper_json(fullfile(folder,'provenance.json'),struct('case_id',s.id,'upstream_baseline_git_sha',p.git_sha,'implementation_manifest','config/source_manifest.json','model_path',b.model_path,'model_sha256',b.model_sha256,'bank_sha256',b.bank_sha256,'controller',s.method,'case_config_sha256',paper_hash(fullfile(folder,'case_config.json')),'PID_step_sha256',paper_hash(which('v3_pid_step'))));end
clear c;v3_overview(out);
end
